// probes/powerups-aid/physical-placement.mjs
// Generated by probes/powerups-aid/tools/build_physical_placement.mjs from
// probes/powerups-aid/tools/physical_placement_module.template.mjs and
// probes/powerups-aid/data/physical-placement.json. Do not edit by hand.
//
// Browser-importable true world-position retail pickup placement for the
// e1-drive power-up slice.
//
// Contract:
//   import {
//     PHYSICAL_PLACEMENT_SCHEMA, PHYSICAL_PLACEMENT_DATA,
//     physicalPlacementsFor
//   } from './physical-placement.mjs';
//   const set = physicalPlacementsFor('amboy', layout);
//   // layout is the measured layout the page drives:
//   //   { course: { lengthMetres, band|corridor, samples: [{arc,x,z,groundY}, ...] } }
//   // set = { schema, mapId, physicalProjection: true, source, pickups, offCourse,
//   //         unsupported, counts }
//
// Rule: each retail pickup is reconstructed on its committed retail .aid racing
// line from the decoded route, arc and lateral. If that retail world position is
// inside the measured band it is placed there (x/z = retail world, y = nearest
// measured sample groundY). Otherwise it stays off-course with its exact distance
// to the measured band and its nearest measured arc. There is no arc-fraction
// remap and no pickup is moved onto the course.

export const PHYSICAL_PLACEMENT_SCHEMA = 'blur.powerups-aid-physical-placement/1';
export const PHYSICAL_PLACEMENT_DATA_SCHEMA = 'blur.powerups-aid-physical-placement-source/1';

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

function fail(message) {
  throw new Error('physical-placement: ' + message);
}

function round6(value) {
  const rounded = Math.round(value * 1e6) / 1e6;
  return Object.is(rounded, -0) ? 0 : rounded;
}

function bandOf(layout) {
  const band = layout?.course?.band?.halfWidthMetres;
  if (Number.isFinite(band) && band > 0) {
    return { halfWidthMetres: band, source: 'course.band.halfWidthMetres' };
  }
  const corridor = layout?.course?.corridor?.halfWidthMetres;
  if (Number.isFinite(corridor) && corridor > 0) {
    return { halfWidthMetres: corridor, source: 'course.corridor.halfWidthMetres' };
  }
  return null;
}

function measuredLengthOf(layout) {
  const length = layout?.course?.lengthMetres;
  if (Number.isFinite(length) && length > 0) return length;
  const samples = layout?.course?.samples;
  if (Array.isArray(samples) && samples.length > 0) {
    const last = samples[samples.length - 1];
    if (Number.isFinite(last?.arc) && last.arc > 0) return last.arc;
  }
  return null;
}

/**
 * Clamped segment projection of a world XZ point onto the measured polyline.
 * Ties keep the earlier segment.
 */
function nearestOnMeasured(samples, x, z) {
  let best = { distance: Infinity, arc: 0, index: 0 };
  for (let index = 0; index < samples.length - 1; index++) {
    const a = samples[index];
    const b = samples[index + 1];
    const vx = (b.x ?? 0) - (a.x ?? 0);
    const vz = (b.z ?? 0) - (a.z ?? 0);
    const lengthSquared = vx * vx + vz * vz;
    let t = lengthSquared > 0
      ? ((x - (a.x ?? 0)) * vx + (z - (a.z ?? 0)) * vz) / lengthSquared
      : 0;
    t = Math.max(0, Math.min(1, t));
    const px = (a.x ?? 0) + vx * t;
    const pz = (a.z ?? 0) + vz * t;
    const distance = Math.hypot(x - px, z - pz);
    if (distance < best.distance) {
      const arcStart = a.arc ?? 0;
      const arcEnd = b.arc ?? arcStart;
      best = { distance, arc: arcStart + (arcEnd - arcStart) * t, index };
    }
  }
  return best;
}

function nearestSampleIndex(samples, targetArc) {
  let bestIndex = 0;
  let bestDelta = Math.abs((samples[0].arc ?? 0) - targetArc);
  for (let index = 1; index < samples.length; index++) {
    const delta = Math.abs((samples[index].arc ?? 0) - targetArc);
    if (delta < bestDelta) {
      bestIndex = index;
      bestDelta = delta;
    }
  }
  return bestIndex;
}

function groundAt(samples, index) {
  const sample = samples[index];
  return sample.groundY ?? sample.height ?? 0;
}

export const PHYSICAL_PLACEMENT_DATA = deepFreeze(/*__PHYSICAL_PLACEMENT_DATA__*/);

/**
 * Place the retail pickups of a map at their retail world position when that
 * position is inside the measured band; keep every other pickup off-course.
 *
 * @param {'amboy'|'gracia'|'river'} mapId
 * @param {{course:{lengthMetres:number,band?:{halfWidthMetres:number},
 *   corridor?:{halfWidthMetres:number},samples:Array<{arc:number,x:number,z:number,groundY?:number}>}}} layout
 * @returns {{schema:string, mapId:string, physicalProjection:boolean, source:string,
 *   pickups:Array<object>, offCourse:Array<object>, unsupported:Array<object>,
 *   counts:{retailPlacements:number,placeable:number,offCourse:number,unsupported:number}}}
 */
export function physicalPlacementsFor(mapId, layout) {
  const map = PHYSICAL_PLACEMENT_DATA.maps[mapId];
  if (!map) {
    fail('unknown map ' + JSON.stringify(mapId) + ' (use ' +
      Object.keys(PHYSICAL_PLACEMENT_DATA.maps).join(', ') + ')');
  }
  const samples = layout?.course?.samples;
  const band = bandOf(layout);
  const layoutId = layout?.courseId ?? layout?.course?.name ?? map.measuredLayout.id;
  const pickups = [];
  const offCourse = [];
  const unsupported = [];

  if (!Array.isArray(samples) || samples.length === 0) {
    for (const row of map.rows) {
      unsupported.push({
        id: mapId + ':' + row.uid,
        uid: row.uid,
        type: row.type,
        reason: 'no-measured-sample: layout.course.samples is empty; the retail world ' +
          'position cannot be tested against a band'
      });
    }
    return {
      schema: PHYSICAL_PLACEMENT_SCHEMA,
      mapId,
      physicalProjection: true,
      source: 'retail world-position band test for ' + mapId + ': no measured samples',
      pickups,
      offCourse,
      unsupported,
      counts: {
        retailPlacements: map.rows.length,
        placeable: 0,
        offCourse: 0,
        unsupported: unsupported.length
      }
    };
  }
  if (!band) {
    for (const row of map.rows) {
      unsupported.push({
        id: mapId + ':' + row.uid,
        uid: row.uid,
        type: row.type,
        reason: 'no-band: layout has neither course.band.halfWidthMetres nor ' +
          'course.corridor.halfWidthMetres'
      });
    }
    return {
      schema: PHYSICAL_PLACEMENT_SCHEMA,
      mapId,
      physicalProjection: true,
      source: 'retail world-position band test for ' + mapId + ': no measured band',
      pickups,
      offCourse,
      unsupported,
      counts: {
        retailPlacements: map.rows.length,
        placeable: 0,
        offCourse: 0,
        unsupported: unsupported.length
      }
    };
  }

  for (const row of map.rows) {
    const id = mapId + ':' + row.uid;
    const hit = nearestOnMeasured(samples, row.retailWorldX, row.retailWorldZ);
    const sampleIndex = nearestSampleIndex(samples, hit.arc);
    const inside = hit.distance <= band.halfWidthMetres + 1e-9;

    if (inside) {
      pickups.push({
        id,
        uid: row.uid,
        type: row.type,
        x: round6(row.retailWorldX),
        y: round6(groundAt(samples, sampleIndex)),
        z: round6(row.retailWorldZ),
        arc: round6(hit.arc),
        measuredArc: round6(hit.arc),
        retailArc: round6(row.retailArc),
        routeLengthM: round6(row.routeLengthM),
        lateral: round6(row.lateral),
        retailLateral: round6(row.lateral),
        route: row.route,
        routeIndex: row.routeIndex,
        segment: row.segment,
        aidResidualM: round6(row.aidResidualM),
        residualM: round6(hit.distance),
        sampleIndex,
        physicalProjection: true,
        source: 'retail uid ' + row.uid + ' route ' + row.route +
          ' (index ' + row.routeIndex + ') retail arc ' + row.retailArc.toFixed(6) +
          ' m, lateral ' + row.lateral.toFixed(6) + ' m -> .aid world (' +
          row.retailWorldX.toFixed(6) + ', ' + row.retailWorldZ.toFixed(6) +
          ') (normal sign ' + row.normalSign + ', residual to committed position ' +
          row.aidResidualM.toFixed(6) + ' m) -> measured ' + layoutId + ' arc ' +
          hit.arc.toFixed(6) + ' m, centreline distance ' + hit.distance.toFixed(6) +
          ' m <= band +/-' + band.halfWidthMetres.toFixed(6) + ' m (' + band.source +
          '), groundY ' + groundAt(samples, sampleIndex).toFixed(6) + ' m from sample ' +
          sampleIndex + ' of ' + samples.length + '; rule retail-world-position-band-test; ' +
          'physicalProjection true'
      });
    } else {
      offCourse.push({
        id,
        uid: row.uid,
        type: row.type,
        reason: 'off-course: retail world position (' + row.retailWorldX.toFixed(6) +
          ', ' + row.retailWorldZ.toFixed(6) + ') is ' + hit.distance.toFixed(6) +
          ' m from the measured ' + layoutId + ' centreline, ' +
          (hit.distance - band.halfWidthMetres).toFixed(6) + ' m outside the +/-' +
          band.halfWidthMetres.toFixed(6) + ' m band (' + band.source +
          '); nearest measured arc ' + hit.arc.toFixed(6) + ' m; retail arc ' +
          row.retailArc.toFixed(6) + ' m on route ' + row.route + ' (index ' +
          row.routeIndex + ')',
        x: round6(row.retailWorldX),
        z: round6(row.retailWorldZ),
        retailArc: round6(row.retailArc),
        nearestMeasuredArc: round6(hit.arc),
        distanceToCourseM: round6(hit.distance),
        distanceToBandM: round6(hit.distance - band.halfWidthMetres),
        route: row.route,
        routeIndex: row.routeIndex,
        segment: row.segment,
        aidResidualM: round6(row.aidResidualM)
      });
    }
  }

  return {
    schema: PHYSICAL_PLACEMENT_SCHEMA,
    mapId,
    physicalProjection: true,
    source: 'retail world-position band test for ' + mapId + ' on measured layout ' +
      layoutId + ' (' + (measuredLengthOf(layout) ?? 0).toFixed(6) + ' m, band +/-' +
      band.halfWidthMetres.toFixed(6) + ' m from ' + band.source + '); rule ' +
      'retail-world-position-band-test; retail routes and arcs from ' +
      'probes/powerups/data/pickup-routes.json; off-course pickups are not moved',
    pickups,
    offCourse,
    unsupported,
    counts: {
      retailPlacements: map.rows.length,
      placeable: pickups.length,
      offCourse: offCourse.length,
      unsupported: unsupported.length
    }
  };
}
